#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
int main(){try{using namespace moon;const auto v=pickerMoonVertices();CHECK(std::abs(v[0].x-.914)<1e-12&&v[0].y==.5);CHECK(pickerMoonTriangleColor(0,{1,0,0})==0xff0000ffu);CHECK(pickerMoonTriangleColor(73,{0,1,0})==0xffffffffu);CHECK(pickerMoonTriangleColor(73,{0,0,1})==0xff000000u);CHECK(pickerMoonTriangleColor(0,{0,.5,.5},55)==0x37808080u);for(int i=0;i<3;++i){auto w=pickerMoonClosest(v[i].x,v[i].y);CHECK(std::abs((i==0?w.tip:i==1?w.white:w.black)-1)<1e-12);}CHECK(std::abs(pickerMoonClosest(2,.5).tip-1)<1e-12);CHECK(!pickerMoonInside(.05,.05));CHECK(!pickerMoonCenterColor(.5,.04,0,PickerMoonField::HsvSquare));CHECK(pickerMoonCenterColor(.5,.5,0,PickerMoonField::HsvSquare).value()==0xff404080u);CHECK(pickerMoonRingColor(.96,.5)==0xff80ff00u);CHECK(pickerMoonRingColor(.5,.5)==0);const auto hm=pickerMoonHueMarker(150);CHECK(std::abs(hm.first-.96)<1e-12&&std::abs(hm.second-.5)<1e-12);PickerRole role;role.sync(0x370000ffu);role.hsv.h=33;PickerMoonGesture gesture;gesture.sample(role,PickerMoonField::HsvSquare,.5,.5);CHECK(gesture.zone==PickerMoonGesture::Zone::Center&&role.hsv.h==33);gesture.sample(role,PickerMoonField::HsvSquare,.96,.5);CHECK(role.hsv.h==33&&role.hsv.s==1&&int(role.color>>24)==55);gesture.reset();gesture.sample(role,PickerMoonField::HsvSquare,1,0);CHECK(gesture.zone==PickerMoonGesture::Zone::Hue&&std::abs(role.hsv.h-105)<1e-12);gesture.sample(role,PickerMoonField::HsvSquare,.5,.5);CHECK(gesture.zone==PickerMoonGesture::Zone::Hue&&role.hsv.h==150);role.hsv={217,.7,.8};role.emit();gesture.reset();gesture.sample(role,PickerMoonField::HslTriangle,v[1].x,v[1].y);CHECK(role.color==0x37ffffffu&&role.hsv.h==217);gesture.sample(role,PickerMoonField::HslTriangle,v[0].x,v[0].y);CHECK(role.hsv.h==217&&role.hsv.s==1&&role.hsv.v==1&&int(role.color>>24)==55);CHECK(parseColorPickerScheme("moon-ring")==ColorPickerScheme::MoonRing);CHECK(parsePickerMoonField("invalid")==PickerMoonField::HsvSquare);std::cout<<"Moon ring geometry/HSV/HSL/gesture passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
